mapper.select:
SELECT p.id AS productId, p.name AS productName, p.type AS productType, SUM(flow.amount) AS totalRevenue, SUM(flow.quantity) AS totalQuantity FROM ( SELECT oi.product_id AS productId, oi.gross_amount - oi.coupon_discount_amount AS amount, oi.qty AS quantity, o.paid_at AS occurredAt FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE o.paid_at >= #{rangeFrom} AND o.paid_at < #{rangeTo} UNION ALL SELECT oi.product_id AS productId, -(oi.gross_amount - oi.coupon_discount_amount) AS amount, -oi.qty AS quantity, r.succeeded_at AS occurredAt FROM refunds r JOIN order_items oi ON oi.order_id = r.order_id WHERE r.status = 'SUCCEEDED' AND r.order_id IS NOT NULL AND r.order_claim_id IS NULL AND r.succeeded_at >= #{rangeFrom} AND r.succeeded_at < #{rangeTo} UNION ALL SELECT oi.product_id AS productId, -oci.approved_refund_amount AS amount, -oci.quantity AS quantity, r.succeeded_at AS occurredAt FROM refunds r JOIN order_claim_items oci ON oci.claim_id = r.order_claim_id JOIN order_items oi ON oi.id = oci.order_item_id WHERE r.status = 'SUCCEEDED' AND r.order_claim_id IS NOT NULL AND r.succeeded_at >= #{rangeFrom} AND r.succeeded_at < #{rangeTo} ) flow JOIN products p ON p.id = flow.productId GROUP BY p.id, p.name, p.type ORDER BY
totalRevenue DESC totalQuantity DESC
LIMIT #{limit}
